# Balance option lengths across QUIZ_1_4 and QUIZ_5_8 so o[0] (the correct option)
# is NOT guessable by picking the longest string!
def balance_quiz_options(quiz_list):
    suffixes = [
        " inside the current process virtual address space at runtime",
        " whenever the function executes on a 64-bit CPU or GPU target",
        " during standard forward and backward execution passes in production",
    ]
    for idx, q in enumerate(quiz_list):
        opts = list(q["o"])
        # If idx % 3 != 0, make one of the distractors (1, 2, or 3) slightly longer than opts[0]
        if idx % 4 != 0:
            target_d = (idx % 3) + 1
            while len(opts[target_d]) <= len(opts[0]):
                opts[target_d] = opts[target_d].rstrip(".") + suffixes[idx % len(suffixes)]
        q["o"] = opts
    return quiz_list


