def apply_enrichments(quiz_list, exercises_list):
    balance_quiz_options(quiz_list)
    for ex in exercises_list:
        eid = ex["id"]
        if eid in FULL_LINES_CPP:
            ex["lines_cpp"] = FULL_LINES_CPP[eid]
        if eid in FULL_LINES_PY:
            ex["lines_py"] = FULL_LINES_PY[eid]
    return quiz_list, exercises_list
